draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // flames
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  for (let i = 0; i < 10; i++) {
    ctx.lineTo(W/2 + Math.sin(t + i) * 50, H/2 - i * 20 + Math.cos(t + i * 2) * 20);
  }
  ctx.stroke();

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 30);
  ctx.lineTo(W/2 - 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10);
  ctx.lineTo(W/2 - 80, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 10);
  ctx.lineTo(W/2 - 120, H/2 + 20);
  ctx.stroke();

  ctx.restore();
}
